import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CZqXuAiL.js";const m=JSON.parse('{"title":"CLI Commands","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/cli/commands.md","filePath":"openshield-xdp/cli/commands.md","lastUpdated":null}'),r={name:"openshield-xdp/cli/commands.md"};function s(l,t,n,i,c,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="cli-commands" tabindex="-1">CLI Commands <a class="header-anchor" href="#cli-commands" aria-label="Permalink to &quot;CLI Commands&quot;">​</a></h1><p>OpenShield-XDP provides two binaries with different command sets.</p><h2 id="openshield-—-full-cli" tabindex="-1"><code>openshield</code> — Full CLI <a class="header-anchor" href="#openshield-—-full-cli" aria-label="Permalink to &quot;`openshield` — Full CLI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th style="text-align:center;">Requires root</th></tr></thead><tbody><tr><td><code>load</code></td><td>Load and attach XDP program, start TUI dashboard</td><td style="text-align:center;">Yes</td></tr><tr><td><code>unload</code></td><td>Unload XDP program, detach from NIC, clean up</td><td style="text-align:center;">Yes</td></tr><tr><td><code>status</code></td><td>Show current XDP/loader/telemetry/config state</td><td style="text-align:center;">No</td></tr><tr><td><code>reload</code></td><td>Hot-reload configuration via Unix socket</td><td style="text-align:center;">Yes</td></tr><tr><td><code>fix</code></td><td>Auto-detect and repair 7 categories of issues</td><td style="text-align:center;">Yes</td></tr><tr><td><code>tui</code> / <code>stats</code></td><td>Launch standalone TUI dashboard</td><td style="text-align:center;">No</td></tr><tr><td><code>config</code></td><td>Interactive config generator</td><td style="text-align:center;">No</td></tr><tr><td><code>upgrade</code></td><td>Pull latest, rebuild, reinstall (EXPERIMENTAL)</td><td style="text-align:center;">Yes</td></tr><tr><td><code>install</code></td><td>Run the installer script</td><td style="text-align:center;">Yes</td></tr><tr><td><code>version</code></td><td>Show version string</td><td style="text-align:center;">No</td></tr><tr><td><code>help</code></td><td>Show usage help</td><td style="text-align:center;">No</td></tr></tbody></table><h3 id="load-flags" tabindex="-1">Load flags <a class="header-anchor" href="#load-flags" aria-label="Permalink to &quot;Load flags&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-t &lt;seconds&gt;</code></td><td>int</td><td><code>0</code></td><td>Auto-unload after N seconds</td></tr><tr><td><code>--refresh &lt;ms&gt;</code></td><td>int</td><td><code>1000</code></td><td>Stats poll interval in milliseconds</td></tr><tr><td><code>--stats-off</code></td><td>bool</td><td><code>false</code></td><td>Suppress all stats display (daemon mode)</td></tr><tr><td><code>--stats-minimal</code></td><td>bool</td><td><code>false</code></td><td>Print text snapshots instead of TUI</td></tr><tr><td><code>-i &lt;iface&gt;</code></td><td>string</td><td>(config)</td><td>Override <code>interface</code> from config</td></tr><tr><td><code>-m &lt;mode&gt;</code></td><td>string</td><td>(config)</td><td>Override <code>xdp_mode</code>: <code>native</code>, <code>generic</code>, <code>skb</code></td></tr></tbody></table><h3 id="fix-flags" tabindex="-1">Fix flags <a class="header-anchor" href="#fix-flags" aria-label="Permalink to &quot;Fix flags&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Description</th></tr></thead><tbody><tr><td><code>-v</code> / <code>--verbose</code></td><td>Show detail for each repair step</td></tr></tbody></table><h2 id="openshield-loader-—-minimal-daemon-cli" tabindex="-1"><code>openshield-loader</code> — Minimal daemon CLI <a class="header-anchor" href="#openshield-loader-—-minimal-daemon-cli" aria-label="Permalink to &quot;`openshield-loader` — Minimal daemon CLI&quot;">​</a></h2><p>Used by the systemd service. Smaller binary, fewer commands.</p><table tabindex="0"><thead><tr><th>Command</th><th>Description</th><th style="text-align:center;">Requires root</th></tr></thead><tbody><tr><td><code>load</code></td><td>Load XDP with text stats display</td><td style="text-align:center;">Yes</td></tr><tr><td><code>unload</code></td><td>Unload XDP and clean up</td><td style="text-align:center;">Yes</td></tr><tr><td><code>stats</code></td><td>Show live text statistics</td><td style="text-align:center;">No</td></tr><tr><td><code>status</code></td><td>Show current status</td><td style="text-align:center;">No</td></tr><tr><td><code>reload</code></td><td>Reload config without unloading</td><td style="text-align:center;">Yes</td></tr><tr><td><code>version</code></td><td>Show version</td><td style="text-align:center;">No</td></tr><tr><td><code>help</code></td><td>Show usage help</td><td style="text-align:center;">No</td></tr></tbody></table><h3 id="load-flags-loader-variant" tabindex="-1">Load flags (loader variant) <a class="header-anchor" href="#load-flags-loader-variant" aria-label="Permalink to &quot;Load flags (loader variant)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>-t &lt;seconds&gt;</code></td><td>int</td><td><code>0</code></td><td>Auto-unload after N seconds</td></tr><tr><td><code>--stats-off</code></td><td>bool</td><td><code>false</code></td><td>No stats display (daemon mode)</td></tr><tr><td><code>-i &lt;iface&gt;</code></td><td>string</td><td>(config)</td><td>Override interface</td></tr><tr><td><code>-m &lt;mode&gt;</code></td><td>string</td><td>(config)</td><td>Override XDP mode</td></tr></tbody></table><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Code</th><th>Meaning</th></tr></thead><tbody><tr><td style="text-align:center;"><code>0</code></td><td>Success (status: loaded and running)</td></tr><tr><td style="text-align:center;"><code>1</code></td><td>Error or not loaded (status: not running)</td></tr></tbody></table><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>HOME</code></td><td>Used by <code>upgrade</code> to search for Go and repo paths</td></tr><tr><td><code>GOROOT</code></td><td>Used by <code>upgrade</code> to find Go binary</td></tr><tr><td><code>PATH</code></td><td>Used by <code>upgrade</code> for build pipeline</td></tr></tbody></table><h2 id="system-paths" tabindex="-1">System paths <a class="header-anchor" href="#system-paths" aria-label="Permalink to &quot;System paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Used by</th></tr></thead><tbody><tr><td><code>/etc/openshield/openshield.yaml</code></td><td>Config file (all commands)</td></tr><tr><td><code>/var/run/openshield/telemetry.sock</code></td><td>Unix socket (reload, TUI, status)</td></tr><tr><td><code>/var/run/openshield/loader.pid</code></td><td>PID file (status, unload)</td></tr><tr><td><code>/sys/fs/bpf/</code></td><td>BPF filesystem (fix, load, unload)</td></tr><tr><td><code>/opt/openshield/bin/</code></td><td>Installed binaries</td></tr><tr><td><code>/opt/openshield/lib/</code></td><td>BPF object, install script</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><p><a href="/pingless-studios-docs/openshield-xdp/cli/load">Load Deep-Dive</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/status">Status Output</a> · <a href="/pingless-studios-docs/openshield-xdp/cli/fix">Fix Reference</a> · <a href="/pingless-studios-docs/openshield-xdp/user-guide/tui">TUI Guide</a></p>',21)])])}const u=e(r,[["render",s]]);export{m as __pageData,u as default};
